"""Real Host callback routing with a deterministic app-server, not a live model test."""
from pathlib import Path
source=(Path(__file__).parents[1]/'fakes/fake_codex_session.py').read_text(encoding='utf-8')
anchor="    if not core:\n"
probe="    if not core and scenario == 'role-flow':\n        instructions=threads[tid].get('developerInstructions','')\n        project=option('--slug')\n        cwd=option('--project')\n        home=Path(option('--home'))\n        if 'You turn a wish' in instructions:\n            state=tool(tid,turn,'workflow',{'action':'status'})\n            content=json.loads(state['contentItems'][0]['text'])\n            phase=content['workflow']['phase']\n            if phase=='research':\n                denied=tool(tid,turn,'codex_run',{'project':project,'cwd':cwd,'role':'terra','unit':'NO'})\n                assert not denied['success'], denied\n                bad=call(tid,turn,'Agent',{'subagent_type':'chronos:astra','project':project,'cwd':cwd,'prompt':'bad destination','save_to':str(home/'outside-store.json')})\n                assert not bad['success'], bad\n                after=tool(tid,turn,'workflow',{'action':'status'})\n                assert json.loads(after['contentItems'][0]['text'])['workflow']['phase']=='research', after\n                research=call(tid,turn,'Agent',{'subagent_type':'chronos:astra','project':project,'cwd':cwd,'prompt':'Respect user intent; return plan and intent_summary'})\n                assert research['success'], research\n            elif phase=='planning':\n                bad=call(tid,turn,'Agent',{'subagent_type':'chronos:architect','project':project,'cwd':str(home/'missing-project'),'prompt':'bad cwd'})\n                assert not bad['success'], bad\n                after=tool(tid,turn,'workflow',{'action':'status'})\n                assert json.loads(after['contentItems'][0]['text'])['workflow']['phase']=='planning', after\n                result=call(tid,turn,'Agent',{'subagent_type':'chronos:architect','project':project,'cwd':cwd,'prompt':'Split approved research into modules'})\n                assert result['success'], result\n                early=tool(tid,turn,'workflow',{'action':'ready'})\n                assert not early['success'], early\n            complete(tid,turn,'dispatcher boundary')\n        elif 'You decide where' in instructions:\n            path=home/'orchestrate'/project/'modules.md'\n            text='## module\\nPURPOSE tiny CLI\\nPATHS src/ tests/\\nDEPENDS none\\nCONTRACT\\n  stable CLI\\nACCEPT cargo test\\n\\nFULL TEST cargo test\\n'\n            result=call(tid,turn,'Write',{'file_path':str(path),'content':text})\n            assert result['success'], result\n            complete(tid,turn,'module map saved')\n        else:\n            complete(tid,turn,json.dumps({'intent_summary':'Implement exactly the requested tiny CLI, with no unrelated changes.','plan':'one module, test and package'}))\n        return\n"
# Optional deterministic crash point: the host has claimed ResearchRunning,
# but the fake researcher cannot finish until the test releases this marker.
probe=probe.replace("        else:\n            complete(tid,turn,json.dumps", "        else:\n            if option('--pause-research'):\n                marker=Path(option('--pause-research'))\n                marker.write_text('ready', encoding='utf-8')\n                while not marker.with_suffix('.release').exists():\n                    time.sleep(0.02)\n            complete(tid,turn,json.dumps")
assert source.count(anchor)==1
source=source.replace(anchor,probe+anchor)
source=source.replace("    elif method=='model/list':", "    elif method=='thread/unsubscribe': reply(msg,{'status':'unsubscribed'})\n    elif method=='skills/list': reply(msg,{'data':[]})\n    elif method=='model/list':")
exec(compile(source,__file__,'exec'))
